import {useEffect,useState} from "react";
export type Ticket={id:number;status:"OPEN"|"CLOSED"};export function openCount(tickets:readonly Ticket[]):number{return tickets.filter(ticket=>ticket.status==="OPEN").length;}export function titleFor(count:number):string{if(!Number.isSafeInteger(count)||count<0)throw RangeError("Licznik");return count>0?`(${count}) DevDesk`:"DevDesk";}
export function useDocumentTitle(count:number){useEffect(()=>{const previous=document.title;document.title=titleFor(count);return ()=>{document.title=previous;};},[count]);}
export function TicketCounter({tickets}:{tickets:readonly Ticket[]}){const count=openCount(tickets);const [highlight,setHighlight]=useState(false);useDocumentTitle(count);return <button type="button" aria-pressed={highlight} onClick={()=>setHighlight(previous=>!previous)}>Otwarte: {count}</button>;}

